    {
      "narration": "总结一下，固定输出值 z 所得到的平面的投影曲线就是等高线。下一节课，我们将固定输入变量 y，观察纵向截面的抛物线形状。请看课后思考题：若想让投影圆的半径为 √3，请先算出需要的高度，再调节高度验证。",
      "delivery": "encouraging",
      "math_creates": [
        {
          "timing": "before_speech",
          "content": {
            "latex": "r = \\sqrt{h} \\implies h = r^2"
          }
        }
      ],
      "note_creates": [
        {
          "timing": "during_speech",
          "content": {
            "title": "课程总结与预告",
            "items": [
              "固定 z（输出）：得到不同高度的等高线（圆）",
              "固定 y 或 x（输入）：下节预告——垂直截面与抛物线",
              "思考题：若 r = √3，则需要的高度 h 为多少？"
            ]
          }
        }
      ],
      "focuses": [
        {
          "timing": "during_speech",
          "intent": "归纳等高线思想，预告纵向截面分析并布置课后练习"
        }
      ]
    }
  ]
}
